-- Kerno test fixture: PostgreSQL sample schema.
-- A small shop (schema `shop`), an analytics schema and a table holding one
-- column per common type. Deterministic: no random(), no now() in the data.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS hstore;

CREATE ROLE kerno_app NOLOGIN;
CREATE ROLE kerno_readonly LOGIN PASSWORD 'kerno_ro_pw';
CREATE ROLE kerno_cert LOGIN;
GRANT kerno_app TO kerno_readonly;

CREATE SCHEMA shop;
CREATE SCHEMA analytics;
COMMENT ON SCHEMA shop IS 'Orders, customers and the product catalogue';

-- Types ---------------------------------------------------------------------

CREATE TYPE shop.order_status AS ENUM ('pending', 'paid', 'shipped', 'delivered', 'cancelled', 'refunded');
CREATE TYPE shop.address AS (street text, city text, postal_code text, country char(2));
CREATE DOMAIN shop.email AS text CHECK (VALUE ~ '^[^@\s]+@[^@\s]+$');
CREATE SEQUENCE shop.invoice_number_seq START 1000 INCREMENT 1;

-- Tables --------------------------------------------------------------------

CREATE TABLE shop.customers (
    id               bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email            shop.email NOT NULL,
    full_name        text NOT NULL,
    phone            varchar(32),
    is_active        boolean NOT NULL DEFAULT true,
    tags             text[] NOT NULL DEFAULT '{}',
    preferences      jsonb NOT NULL DEFAULT '{}',
    shipping_address shop.address,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT customers_email_key UNIQUE (email)
);
COMMENT ON TABLE shop.customers IS 'People who can place orders';
COMMENT ON COLUMN shop.customers.tags IS 'Free-form labels used by support';

CREATE TABLE shop.categories (
    id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id integer REFERENCES shop.categories (id) ON DELETE SET NULL,
    name      text NOT NULL,
    slug      text NOT NULL UNIQUE
);

CREATE TABLE shop.products (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    public_id   uuid NOT NULL DEFAULT gen_random_uuid(),
    category_id integer NOT NULL REFERENCES shop.categories (id),
    sku         varchar(32) NOT NULL,
    name        text NOT NULL,
    description text,
    price       numeric(10, 2) NOT NULL CHECK (price >= 0),
    stock       integer NOT NULL DEFAULT 0,
    weight_kg   real,
    attributes  jsonb NOT NULL DEFAULT '{}',
    tags        text[] NOT NULL DEFAULT '{}',
    dimensions  numeric(8, 2)[],
    released_on date,
    discontinued boolean NOT NULL DEFAULT false,
    CONSTRAINT products_sku_key UNIQUE (sku),
    CONSTRAINT products_stock_check CHECK (stock >= 0)
);
CREATE INDEX products_category_idx ON shop.products (category_id);
CREATE INDEX products_name_trgm_idx ON shop.products USING gin (name gin_trgm_ops);
CREATE INDEX products_attributes_idx ON shop.products USING gin (attributes);
CREATE INDEX products_active_price_idx ON shop.products (price DESC) WHERE NOT discontinued;

CREATE TABLE shop.orders (
    id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id    bigint NOT NULL REFERENCES shop.customers (id) ON DELETE RESTRICT,
    status         shop.order_status NOT NULL DEFAULT 'pending',
    invoice_number bigint DEFAULT nextval('shop.invoice_number_seq'),
    placed_at      timestamptz NOT NULL,
    shipped_at     timestamp,
    total          numeric(12, 2) NOT NULL DEFAULT 0,
    currency       char(3) NOT NULL DEFAULT 'EUR',
    notes          text
);
CREATE INDEX orders_customer_idx ON shop.orders (customer_id);
CREATE INDEX orders_status_placed_idx ON shop.orders (status, placed_at DESC);

CREATE TABLE shop.order_items (
    order_id   bigint NOT NULL REFERENCES shop.orders (id) ON DELETE CASCADE,
    line_no    smallint NOT NULL,
    product_id bigint NOT NULL REFERENCES shop.products (id),
    quantity   integer NOT NULL CHECK (quantity > 0),
    unit_price numeric(10, 2) NOT NULL,
    PRIMARY KEY (order_id, line_no)
);
CREATE INDEX order_items_product_idx ON shop.order_items (product_id);

CREATE TABLE shop.reviews (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id  bigint NOT NULL REFERENCES shop.products (id) ON DELETE CASCADE,
    customer_id bigint NOT NULL REFERENCES shop.customers (id) ON DELETE CASCADE,
    rating      smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
    title       text,
    body        text,
    created_at  timestamptz NOT NULL,
    CONSTRAINT reviews_once_per_customer UNIQUE (product_id, customer_id)
);

-- No primary key and no unique index on purpose: the data view must open
-- this table read-only and say why.
CREATE TABLE shop.audit_log (
    happened_at timestamptz NOT NULL,
    actor       text NOT NULL,
    action      text NOT NULL,
    payload     jsonb
);

CREATE TABLE analytics.events (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id bigint REFERENCES shop.customers (id) ON DELETE SET NULL,
    event_type  text NOT NULL,
    properties  jsonb NOT NULL DEFAULT '{}',
    occurred_at timestamptz NOT NULL
);
CREATE INDEX events_type_time_idx ON analytics.events (event_type, occurred_at);

-- One column per common type -------------------------------------------------

CREATE TYPE public.mood AS ENUM ('sad', 'ok', 'happy');

CREATE TABLE public.all_types (
    id            integer PRIMARY KEY,
    c_smallint    smallint,
    c_integer     integer,
    c_bigint      bigint,
    c_numeric     numeric(20, 6),
    c_numeric_any numeric,
    c_real        real,
    c_double      double precision,
    c_money       money,
    c_boolean     boolean,
    c_char        char(5),
    c_varchar     varchar(50),
    c_text        text,
    c_bytea       bytea,
    c_date        date,
    c_time        time,
    c_timetz      timetz,
    c_timestamp   timestamp,
    c_timestamptz timestamptz,
    c_interval    interval,
    c_uuid        uuid,
    c_json        json,
    c_jsonb       jsonb,
    c_xml         xml,
    c_inet        inet,
    c_cidr        cidr,
    c_macaddr     macaddr,
    c_int_array   integer[],
    c_text_array  text[],
    c_num_array   numeric[],
    c_int4range   int4range,
    c_tstzrange   tstzrange,
    c_daterange   daterange,
    c_point       point,
    c_bit         bit(8),
    c_varbit      varbit(16),
    c_tsvector    tsvector,
    c_enum        public.mood,
    c_composite   shop.address,
    c_hstore      hstore,
    c_oid         oid,
    c_name        name
);

-- Views ---------------------------------------------------------------------

CREATE VIEW shop.order_totals AS
SELECT o.id AS order_id,
       o.customer_id,
       o.status,
       o.placed_at,
       count(i.line_no) AS line_count,
       coalesce(sum(i.quantity * i.unit_price), 0)::numeric(12, 2) AS computed_total
FROM shop.orders o
LEFT JOIN shop.order_items i ON i.order_id = o.id
GROUP BY o.id;
COMMENT ON VIEW shop.order_totals IS 'Order totals recomputed from the lines';

CREATE MATERIALIZED VIEW shop.product_sales AS
SELECT p.id AS product_id,
       p.sku,
       p.name,
       coalesce(sum(i.quantity), 0)::bigint AS units_sold,
       coalesce(sum(i.quantity * i.unit_price), 0)::numeric(14, 2) AS revenue
FROM shop.products p
LEFT JOIN shop.order_items i ON i.product_id = p.id
GROUP BY p.id
WITH NO DATA;
CREATE UNIQUE INDEX product_sales_product_idx ON shop.product_sales (product_id);

-- Functions, procedures, triggers --------------------------------------------

CREATE FUNCTION shop.customer_lifetime_value(p_customer_id bigint)
RETURNS numeric
LANGUAGE sql
STABLE
AS $$
    SELECT coalesce(sum(total), 0)
    FROM shop.orders
    WHERE customer_id = p_customer_id
      AND status IN ('paid', 'shipped', 'delivered');
$$;
COMMENT ON FUNCTION shop.customer_lifetime_value(bigint) IS 'Sum of the paid orders of a customer';

CREATE FUNCTION shop.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE FUNCTION shop.log_order_status()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO shop.audit_log (happened_at, actor, action, payload)
        VALUES (now(), current_user, 'order_status',
                jsonb_build_object('order_id', NEW.id, 'from', OLD.status, 'to', NEW.status));
    END IF;
    RETURN NEW;
END;
$$;

CREATE PROCEDURE shop.cancel_stale_orders(p_older_than interval)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE shop.orders
    SET status = 'cancelled'
    WHERE status = 'pending'
      AND placed_at < now() - p_older_than;
END;
$$;

CREATE FUNCTION shop.slow_notice(p_seconds double precision)
RETURNS text
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE NOTICE 'sleeping for % s', p_seconds;
    PERFORM pg_sleep(p_seconds);
    RAISE WARNING 'slept for % s', p_seconds;
    RETURN 'done';
END;
$$;

CREATE TRIGGER customers_set_updated_at
    BEFORE UPDATE ON shop.customers
    FOR EACH ROW EXECUTE FUNCTION shop.set_updated_at();

CREATE TRIGGER orders_log_status
    AFTER UPDATE OF status ON shop.orders
    FOR EACH ROW EXECUTE FUNCTION shop.log_order_status();

-- Grants (read by the roles/grants view) -------------------------------------

GRANT USAGE ON SCHEMA shop, analytics TO kerno_app;
GRANT SELECT ON ALL TABLES IN SCHEMA shop TO kerno_app;
GRANT SELECT, INSERT ON shop.audit_log TO kerno_readonly;
